<?php
class AnnouncementService
{
 private $pdo; public function __construct($pdo){$this->pdo=$pdo;}
 private function transaction($fn){$own=!$this->pdo->inTransaction();if($own)$this->pdo->beginTransaction();try{$r=$fn();if($own)$this->pdo->commit();return $r;}catch(Throwable $e){if($own&&$this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
 public function listActive($limit=50){$limit=max(1,min(100,(int)$limit));$now=date('Y-m-d H:i:s');$s=$this->pdo->prepare('SELECT * FROM announcements WHERE status="published" AND starts_at<=? AND (ends_at IS NULL OR ends_at>?) ORDER BY pinned DESC,starts_at DESC,id DESC LIMIT '.$limit);$s->execute(array($now,$now));return $s->fetchAll(PDO::FETCH_ASSOC);}
 public function findActive($id){$now=date('Y-m-d H:i:s');$s=$this->pdo->prepare('SELECT * FROM announcements WHERE id=? AND status="published" AND starts_at<=? AND (ends_at IS NULL OR ends_at>?)');$s->execute(array((int)$id,$now,$now));$r=$s->fetch(PDO::FETCH_ASSOC);return $r?:null;}
 public function find($id){$s=$this->pdo->prepare('SELECT * FROM announcements WHERE id=?');$s->execute(array((int)$id));$r=$s->fetch(PDO::FETCH_ASSOC);return $r?:null;}
 public function adminList($page=1,$perPage=20){$page=max(1,(int)$page);$perPage=max(1,min(50,(int)$perPage));$total=(int)$this->pdo->query('SELECT COUNT(*) FROM announcements')->fetchColumn();$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$offset=($page-1)*$perPage;$s=$this->pdo->query('SELECT * FROM announcements ORDER BY updated_at DESC,id DESC LIMIT '.$offset.','.$perPage);return array('items'=>$s->fetchAll(PDO::FETCH_ASSOC),'total'=>$total,'page'=>$page,'pages'=>$pages);}
 public function create($adminId,$type,$title,$body,$startsAt,$endsAt=null,$pinned=0){$this->admin($adminId);$this->validate($type,$title,$body,$startsAt,$endsAt);return $this->transaction(function()use($adminId,$type,$title,$body,$startsAt,$endsAt,$pinned){$now=date('Y-m-d H:i:s');$s=$this->pdo->prepare('INSERT INTO announcements(type,title,body,status,starts_at,ends_at,pinned,admin_id,version,created_at,updated_at) VALUES(?,?,?,"draft",?,?,?,?,1,?,?)');$s->execute(array($type,$title,$body,$startsAt,$endsAt,(int)$pinned,(int)$adminId,$now,$now));$id=(int)$this->pdo->lastInsertId();$this->audit($adminId,'create_announcement',$id,array('type'=>$type,'title'=>$title));return $id;});}
 private function admin($id){$s=$this->pdo->prepare('SELECT id FROM admin_users WHERE id=? AND status="active"');$s->execute(array((int)$id));if(!$s->fetchColumn())throw new RuntimeException('管理员身份无效。');}
 private function audit($adminId,$action,$id,$details){$s=$this->pdo->prepare('INSERT INTO admin_logs(admin_id,action,target_type,target_id,details_json,created_at) VALUES(?,?,?,?,?,?)');$s->execute(array((int)$adminId,$action,'announcement',(int)$id,json_encode($details,JSON_UNESCAPED_UNICODE),date('Y-m-d H:i:s')));}
 private function validate($type,$title,$body,$start,$end){if(!in_array($type,array('system','maintenance'),true))throw new InvalidArgumentException('公告类型无效。');if(!is_string($title)||!is_string($body)||mb_strlen(trim($title),'UTF-8')<1||mb_strlen($title,'UTF-8')>200||mb_strlen(trim($body),'UTF-8')<1||mb_strlen($body,'UTF-8')>50000)throw new InvalidArgumentException('公告内容长度无效。');$fmt=function($v){$d=DateTime::createFromFormat('Y-m-d H:i:s',$v);return $d&&$d->format('Y-m-d H:i:s')===$v;};if(!is_string($start)||!$fmt($start)||($end!==null&&(!is_string($end)||!$fmt($end)||$end<=$start)))throw new InvalidArgumentException('公告时间区间无效。');}
 public function update($id,$adminId,$version,$type,$title,$body,$startsAt,$endsAt=null,$pinned=0){$this->admin($adminId);$this->validate($type,$title,$body,$startsAt,$endsAt);return $this->transaction(function()use($id,$adminId,$version,$type,$title,$body,$startsAt,$endsAt,$pinned){$s=$this->pdo->prepare('UPDATE announcements SET type=?,title=?,body=?,starts_at=?,ends_at=?,pinned=?,admin_id=?,version=version+1,updated_at=? WHERE id=? AND version=?');$s->execute(array($type,trim($title),$body,$startsAt,$endsAt,(int)$pinned,(int)$adminId,date('Y-m-d H:i:s'),(int)$id,(int)$version));if(!$s->rowCount())throw new RuntimeException('公告已被修改，请刷新后重试。');$this->audit($adminId,'update_announcement',$id,array('version'=>$version));});}
 public function publish($id,$adminId,$version){$this->admin($adminId);return $this->transaction(function()use($id,$adminId,$version){$s=$this->pdo->prepare('UPDATE announcements SET status="published",admin_id=?,version=version+1,updated_at=? WHERE id=? AND version=?');$s->execute(array((int)$adminId,date('Y-m-d H:i:s'),(int)$id,(int)$version));if(!$s->rowCount())throw new RuntimeException('公告已被修改，请刷新后重试。');$this->audit($adminId,'publish_announcement',$id,array('version'=>$version));});}
 public function withdraw($id,$adminId,$version){$this->admin($adminId);return $this->transaction(function()use($id,$adminId,$version){$s=$this->pdo->prepare('UPDATE announcements SET status="withdrawn",admin_id=?,version=version+1,updated_at=? WHERE id=? AND version=?');$s->execute(array((int)$adminId,date('Y-m-d H:i:s'),(int)$id,(int)$version));if(!$s->rowCount())throw new RuntimeException('公告已被修改，请刷新后重试。');$this->audit($adminId,'withdraw_announcement',$id,array('version'=>$version));});}
}
